function createBaseMessage(): Message {
  return { id: "", type: 0, link: "", author: "", title: "", content: "", dateTimestamp: 0, attachmentsDir: "" };
}

export const Message: MessageFns<Message> = {
  encode(message: Message, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.id !== "") {
      writer.uint32(10).string(message.id);
    }
    if (message.type !== 0) {
      writer.uint32(16).int32(message.type);
    }
    if (message.link !== "") {
      writer.uint32(26).string(message.link);
    }
    if (message.author !== "") {
      writer.uint32(34).string(message.author);
    }
    if (message.title !== "") {
      writer.uint32(42).string(message.title);
    }
    if (message.content !== "") {
      writer.uint32(50).string(message.content);
    }
    if (message.dateTimestamp !== 0) {
      writer.uint32(56).int64(message.dateTimestamp);
    }
    if (message.attachmentsDir !== "") {
      writer.uint32(66).string(message.attachmentsDir);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): Message {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseMessage();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 10) {
            break;
          }

          message.id = reader.string();
          continue;
        }
        case 2: {
          if (tag !== 16) {
            break;
          }

          message.type = reader.int32() as any;
          continue;
        }
        case 3: {
          if (tag !== 26) {
            break;
          }

          message.link = reader.string();
          continue;
        }
        case 4: {
          if (tag !== 34) {
            break;
          }

          message.author = reader.string();
          continue;
        }
        case 5: {
          if (tag !== 42) {
            break;
          }

          message.title = reader.string();
          continue;
        }
        case 6: {
          if (tag !== 50) {
            break;
          }

          message.content = reader.string();
          continue;
        }
        case 7: {
          if (tag !== 56) {
            break;
          }

          message.dateTimestamp = longToNumber(reader.int64());
          continue;
        }
        case 8: {
          if (tag !== 66) {
            break;
          }

          message.attachmentsDir = reader.string();
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): Message {
    return {
      id: isSet(object.id) ? globalThis.String(object.id) : "",
      type: isSet(object.type) ? messageTypeFromJSON(object.type) : 0,
      link: isSet(object.link) ? globalThis.String(object.link) : "",
      author: isSet(object.author) ? globalThis.String(object.author) : "",
      title: isSet(object.title) ? globalThis.String(object.title) : "",
      content: isSet(object.content) ? globalThis.String(object.content) : "",
      dateTimestamp: isSet(object.dateTimestamp) ? globalThis.Number(object.dateTimestamp) : 0,
      attachmentsDir: isSet(object.attachmentsDir) ? globalThis.String(object.attachmentsDir) : "",
    };
  },

  toJSON(message: Message): unknown {
    const obj: any = {};
    if (message.id !== "") {
      obj.id = message.id;
    }
    if (message.type !== 0) {
      obj.type = messageTypeToJSON(message.type);
    }
    if (message.link !== "") {
      obj.link = message.link;
    }
    if (message.author !== "") {
      obj.author = message.author;
    }
    if (message.title !== "") {
      obj.title = message.title;
    }
    if (message.content !== "") {
      obj.content = message.content;
    }
    if (message.dateTimestamp !== 0) {
      obj.dateTimestamp = Math.round(message.dateTimestamp);
    }
    if (message.attachmentsDir !== "") {
      obj.attachmentsDir = message.attachmentsDir;
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<Message>, I>>(base?: I): Message {
    return Message.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<Message>, I>>(object: I): Message {
    const message = createBaseMessage();
    message.id = object.id ?? "";
    message.type = object.type ?? 0;
    message.link = object.link ?? "";
    message.author = object.author ?? "";
    message.title = object.title ?? "";
    message.content = object.content ?? "";
    message.dateTimestamp = object.dateTimestamp ?? 0;
    message.attachmentsDir = object.attachmentsDir ?? "";
    return message;
  },
};

